import java.io.*;
import java.util.*;
import java.util.function.BiFunction;

public final class Solution {

  static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
  static BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

  static class Rec {
    int a, b;
    long c;
    Rec(int a, int b, long c) { this.a = a; this.b = b; this.c = c; }
  }

  static class Pair<F, S> {
    F first;
    S second;
    Pair(F f, S s) { first = f; second = s; }
  }

  static class PairComp implements Comparator<Pair<Integer, Integer>> {
    public int compare(Pair<Integer, Integer> p1, Pair<Integer, Integer> p2) {
      return Integer.compare(p1.first, p2.first);
    }
  }

  static int modAdd(int a, int b, int mod) {
    return (int) ((1L * (a % mod) + (b % mod)) % mod);
  }

  static int modSub(int a, int b, int mod) {
    return (int) ((1L * (a % mod) - (b % mod) + mod) % mod);
  }

  static int modMul(int a, int b, int mod) {
    return (int) ((1L * (a % mod) * (b % mod)) % mod);
  }

  static int modPow(int base, int exp, int mod) {
    int res = 1;
    base %= mod;
    while (exp > 0) {
      if ((exp & 1) == 1) res = modMul(res, base, mod);
      base = modMul(base, base, mod);
      exp >>= 1;
    }
    return res;
  }

  static int modDiv(int a, int b, int mod) {
    return modMul(a, modPow(b, mod - 2, mod), mod);
  }

  static int gcd(int a, int b) {
    while (b != 0) { int t = b; b = a % b; a = t; }
    return a;
  }

  static int lowerBound(int[] arr, int val) {
    int lo = 0, hi = arr.length - 1, ans = -1;
    while (lo <= hi) {
      int mid = lo + (hi - lo) / 2;
      if (arr[mid] < val) { ans = mid; lo = mid + 1; }
      else hi = mid - 1;
    }
    return ans;
  }

  static long[] logSeries(long limit, long target) {
    long i = 1, sum = 0;
    int cnt = 0;
    long[] res = new long[2];
    while (i < limit) {
      sum += i;
      cnt++;
      if (sum == target) { res[0] = cnt; res[1] = sum; return res; }
      i *= 2;
    }
    res[0] = cnt; res[1] = sum;
    return res;
  }

  static void addCount(Map<Integer, Integer> map, int key) {
    map.merge(key, 1, Integer::sum);
  }

  static long listSum(List<Long> list) {
    return list.stream().mapToLong(Long::longValue).sum();
  }

  static int charIndex(char c) { return c - 'a'; }

  static int optimizedSearch(int[] prefix, int start, int target, int n) {
    int lo = start + 1, hi = n - 1, ans = start;
    while (lo <= hi) {
      int mid = lo + (hi - lo) / 2;
      int diff = prefix[mid] - prefix[start];
      if (diff == target) return mid;
      if (diff < target) { ans = mid; lo = mid + 1; }
      else hi = mid - 1;
    }
    return ans;
  }

  static Pair<Long, Integer> computeStats(List<Integer> list) {
    long total = 0;
    int minVal = Integer.MAX_VALUE;
    for (int x : list) {
      total += x;
      minVal = Math.min(minVal, x);
    }
    return new Pair<>(total - minVal, minVal);
  }

  static int maxDivisor(Map<Integer, Integer> map, int num, int req) {
    int maxK = 0;
    for (int i = 1; i * i <= num; i++) {
      if (num % i == 0) {
        int d1 = i, d2 = num / i;
        addCount(map, d1);
        if (d1 != d2) addCount(map, d2);
        if (map.get(d1) == req) maxK = Math.max(maxK, d1);
        if (map.get(d2) == req) maxK = Math.max(maxK, d2);
      }
    }
    return maxK;
  }

  static List<Integer> extractKeys(Map<Integer, Integer> map) {
    return new ArrayList<>(map.keySet());
  }

  static List<Integer> extractValues(Map<Integer, Integer> map) {
    return new ArrayList<>(map.values());
  }

  static int arrayMax(List<Integer> list) {
    return list.stream().mapToInt(Integer::intValue).max().orElse(0);
  }

  static int arrayMin(List<Integer> list) {
    return list.stream().mapToInt(Integer::intValue).min().orElse(0);
  }

  static final int[][] MOVES = {{-1,0},{0,1},{1,0},{0,-1}};

  public static void main(String[] args) throws IOException {
    String s = br.readLine();
    int n = s.length();
    int ways = 0;

    if (n == 1) {
      char c = s.charAt(0);
      ways = (c == '0' || c == '_' || c == 'X') ? 1 : 0;
    } else if (s.charAt(0) == '0') {
      ways = 0;
    } else {
      String[] validEnds = {"25", "50", "75", "00"};
      String[] wildEnds = {"__", "_X", "X_", "XX"};
      String tail = s.substring(n - 2);
      char c0 = tail.charAt(0), c1 = tail.charAt(1);

      if (c0 == 'X' && c1 == 'X' && s.charAt(0) == 'X') {
        ways = 0;
      } else {
        for (String end : validEnds) {
          if (tail.equals(end)) { ways = 1; break; }
        }

        if (ways == 0) {
          if (c0 == '_' || c0 == 'X') {
            ways = 2;
            if (c1 == '0' && s.charAt(0) == 'X') ways = 1;
          } else if (c1 == '_' || c1 == 'X') {
            ways = 1;
          }

          for (int i = 0; i < 4; i++) {
            if (tail.equals(wildEnds[i])) {
              if (i == 0) ways = (n == 2) ? 3 : 4;
              else if (i == 1) ways = (s.charAt(0) == 'X') ? 2 : 4;
              else if (i == 2) ways = (s.charAt(0) == 'X') ? 3 : 4;
              else if (i == 3) ways = 1;
            }
          }
        }

        if (c0 != '2' && c0 != '5' && c0 != '7' && c0 != '0' && c0 != 'X' && c0 != '_') ways = 0;
        if (c1 != '0' && c1 != '5' && c1 != 'X' && c1 != '_') ways = 0;

        long multiplier = 1;
        boolean hasX = false;
        for (int i = 0; i < n - 2; i++) {
          if (s.charAt(i) == 'X') hasX = true;
          if (s.charAt(i) == '_') multiplier *= (i == 0) ? 9 : 10;
        }

        if (c0 != 'X' && c1 != 'X') {
          if (hasX) multiplier *= (s.charAt(0) == 'X') ? 9 : 10;
        }

        ways = Math.max(ways, 0);
        multiplier *= ways;
        ways = (int) multiplier;
      }
    }

    bw.write(ways + "\n");
    bw.flush();
  }
}
